import 'dart:async';
import 'package:flutter/material.dart';
import 'appointment_store.dart';

class AuthGate extends StatefulWidget { const AuthGate({super.key,required this.child}); final Widget child; @override State<AuthGate> createState()=>_AuthGateState(); }
class _AuthGateState extends State<AuthGate>{
 bool _loading=true,_register=false,_registerAsAdmin=false; String? _message;
 final _email=TextEditingController(),_password=TextEditingController(),_fullName=TextEditingController(),_barbershopName=TextEditingController(); StreamSubscription? _authSubscription;
 @override void initState(){super.initState();_authSubscription=AppointmentStore.client.auth.onAuthStateChange.listen((_){if(mounted)_refresh();});_refresh();}
 @override void dispose(){_authSubscription?.cancel();_email.dispose();_password.dispose();_fullName.dispose();_barbershopName.dispose();super.dispose();}
 Future<void> _refresh()async{if(!mounted)return;setState(()=>_loading=true);try{if(AppointmentStore.signedIn){await AppointmentStore.refreshMembership();if(!AppointmentStore.hasShop)await _provisionAdminIfNeeded();}}catch(e){_message=_friendlyError(e);}if(mounted)setState(()=>_loading=false);}
 Future<void> _provisionAdminIfNeeded()async{final user=AppointmentStore.currentUser;if(user==null||AppointmentStore.hasShop)return;final metadata=user.userMetadata??const <String,dynamic>{};if(metadata['account_type']!='barbershop_admin')return;final shopName=(metadata['barbershop_name'] as String?)?.trim()??'';if(shopName.length<2)throw StateError('Nome do estabelecimento ausente no cadastro.');await AppointmentStore.client.rpc('bootstrap_barbershop_admin',params:{'p_barbershop_name':shopName});await AppointmentStore.refreshMembership();}
 Future<void> _submitAuth()async{final email=_email.text.trim(),password=_password.text;if(email.isEmpty||password.length<6){setState(()=>_message='Informe um e-mail valido e senha com pelo menos 6 caracteres.');return;}if(_register&&_fullName.text.trim().length<2){setState(()=>_message='Informe seu nome.');return;}if(_register&&_registerAsAdmin&&_barbershopName.text.trim().length<2){setState(()=>_message='Informe o nome do estabelecimento.');return;}setState((){_loading=true;_message=null;});try{if(_register){final data=<String,dynamic>{'full_name':_fullName.text.trim(),'account_type':_registerAsAdmin?'barbershop_admin':'client'};if(_registerAsAdmin)data['barbershop_name']=_barbershopName.text.trim();final response=await AppointmentStore.client.auth.signUp(email:email,password:password,emailRedirectTo:'com.barbeariaagenda.app://login-callback',data:data);if(response.session!=null)await _refresh();else _message='Conta criada. Enviamos um e-mail de confirmacao. Toque no link para concluir o cadastro.';}else{await AppointmentStore.signIn(email,password);if(!AppointmentStore.hasShop)await _provisionAdminIfNeeded();}}catch(e){_message=_friendlyError(e);}if(mounted)setState(()=>_loading=false);}
 String _friendlyError(Object error){final t=error.toString();if(t.contains('Invalid login credentials'))return'E-mail ou senha incorretos.';if(t.contains('Email not confirmed'))return'Confirme seu e-mail antes de entrar.';if(t.contains('already registered'))return'Este e-mail ja possui cadastro.';if(t.contains('Email confirmation required'))return'Confirme seu e-mail antes de continuar.';if(t.contains('Authentication required'))return'Sessao expirada. Entre novamente.';return t;}
 @override Widget build(BuildContext context){if(_loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(!AppointmentStore.signedIn)return _LoginPage(register:_register,registerAsAdmin:_registerAsAdmin,email:_email,password:_password,fullName:_fullName,barbershopName:_barbershopName,message:_message,onSubmit:_submitAuth,onToggle:()=>setState((){_register=!_register;_message=null;}),onAccountTypeChanged:(v)=>setState(()=>_registerAsAdmin=v));if(!AppointmentStore.hasShop){final type=AppointmentStore.currentUser?.userMetadata?['account_type'];if(type=='barbershop_admin')return _ProvisioningPage(email:AppointmentStore.currentUser?.email??'Conta autenticada',message:_message??AppointmentStore.cloudError,onRetry:_refresh,onLogout:_logout);return _ClientShopPage(onSelected:(id)async{setState(()=>_loading=true);try{await AppointmentStore.selectClientShop(id);}catch(e){_message=_friendlyError(e);}if(mounted)setState(()=>_loading=false);},onLogout:_logout);}return widget.child;}
 Future<void> _logout()async{await AppointmentStore.signOut();if(mounted)setState((){});}
}

