 Text(register?(registerAsAdmin?'Cadastre o responsável. O estabelecimento será criado após confirmar o e-mail.':'Crie sua conta de cliente e escolha onde deseja agendar.'):'Sua agenda, serviços e profissionais em um só lugar.',textAlign:TextAlign.center,style:const TextStyle(color:Colors.white60)),const SizedBox(height:24),
 if(register)...[SegmentedButton<bool>(segments:const [ButtonSegment(value:false,label:Text('CLIENTE'),icon:Icon(Icons.person_outline)),ButtonSegment(value:true,label:Text('RESPONSÁVEL'),icon:Icon(Icons.storefront_outlined))],selected:{registerAsAdmin},onSelectionChanged:(s)=>onAccountTypeChanged(s.first)),const SizedBox(height:18),TextField(controller:fullName,textCapitalization:TextCapitalization.words,decoration:const InputDecoration(labelText:'Seu nome',prefixIcon:Icon(Icons.person_outline_rounded),border:OutlineInputBorder())),const SizedBox(height:14),if(registerAsAdmin)...[TextField(controller:barbershopName,textCapitalization:TextCapitalization.words,decoration:const InputDecoration(labelText:'Nome do estabelecimento',prefixIcon:Icon(Icons.storefront_outlined),border:OutlineInputBorder())),const SizedBox(height:14)]],
 TextField(controller:email,keyboardType:TextInputType.emailAddress,autocorrect:false,decoration:const InputDecoration(labelText:'E-mail',prefixIcon:Icon(Icons.mail_outline_rounded),border:OutlineInputBorder())),const SizedBox(height:14),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Senha',prefixIcon:Icon(Icons.lock_outline_rounded),border:OutlineInputBorder())),if(message!=null)...[const SizedBox(height:14),Text(message!,textAlign:TextAlign.center,style:const TextStyle(color:Colors.amberAccent))],const SizedBox(height:20),FilledButton(onPressed:onSubmit,style:FilledButton.styleFrom(backgroundColor:const Color(0xFFD7A84B),foregroundColor:Colors.black,padding:const EdgeInsets.symmetric(vertical:16)),child:Text(register?'CRIAR CONTA':'ENTRAR',style:const TextStyle(fontWeight:FontWeight.w900))),TextButton(onPressed:onToggle,child:Text(register?'Ja tenho conta':'Criar nova conta'))
 ]))))));
}
class _ClientShopPage extends StatefulWidget{const _ClientShopPage({required this.onSelected,required this.onLogout});final Future<void> Function(String) onSelected;final VoidCallback onLogout;@override State<_ClientShopPage> createState()=>_ClientShopPageState();}
class _ClientShopPageState extends State<_ClientShopPage>{late Future<List<Map<String,dynamic>>> _future;@override void initState(){super.initState();_future=AppointmentStore.listActiveBarbershops();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Escolha o estabelecimento'),actions:[IconButton(onPressed:widget.onLogout,icon:const Icon(Icons.logout))]),body:FutureBuilder<List<Map<String,dynamic>>>(future:_future,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Padding(padding:const EdgeInsets.all(24),child:Text('Não foi possível carregar os estabelecimentos.\n${s.error}',textAlign:TextAlign.center)));final shops=s.data??[];if(shops.isEmpty)return const Center(child:Text('Nenhum estabelecimento ativo encontrado.'));return ListView.separated(padding:const EdgeInsets.all(20),itemCount:shops.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(context,i){final shop=shops[i];return Card(child:ListTile(leading:const Icon(Icons.storefront,color:Color(0xFFD7A84B)),title:Text(shop['name']?.toString()??'Estabelecimento'),subtitle:const Text('Toque para acessar e agendar'),trailing:const Icon(Icons.chevron_right),onTap:()=>widget.onSelected(shop['id'].toString())));});}));}
class _ProvisioningPage extends StatelessWidget{const _ProvisioningPage({required this.email,required this.message,required this.onRetry,required this.onLogout});final String email;final String? message;final VoidCallback onRetry,onLogout;@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:420),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.storefront_outlined,size:58,color:Color(0xFFD7A84B)),const SizedBox(height:18),const Text('Configurando seu estabelecimento',textAlign:TextAlign.center,style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const SizedBox(height:8),Text(email,textAlign:TextAlign.center,style:const TextStyle(color:Colors.white60)),const SizedBox(height:24),Text(message??'Aguarde enquanto concluímos seu cadastro.',textAlign:TextAlign.center,style:const TextStyle(color:Colors.amberAccent)),const SizedBox(height:20),FilledButton(onPressed:onRetry,child:const Text('TENTAR NOVAMENTE')),TextButton(onPressed:onLogout,child:const Text('Sair desta conta'))]))))));}
